import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"DevOps & Deploy — Five Platforms, One Command","description":"HF Spaces, Railway, Render, Fly.io, Koyeb, Cloudflare Workers — deploying resilient services on free tiers.","frontmatter":{"title":"DevOps & Deploy — Five Platforms, One Command","description":"HF Spaces, Railway, Render, Fly.io, Koyeb, Cloudflare Workers — deploying resilient services on free tiers."},"headers":[],"relativePath":"en/skills/devops/index.md","filePath":"en/skills/devops/index.md"}`),a={name:`en/skills/devops/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="devops-deploy-—-five-platforms-one-command" tabindex="-1">DevOps &amp; Deploy — Five Platforms, One Command <a class="header-anchor" href="#devops-deploy-—-five-platforms-one-command" aria-label="Permalink to “DevOps &amp; Deploy — Five Platforms, One Command”">​</a></h1><p>Deployment is where hobbies become products. I maintain deploy paths on six platforms and treat &quot;one command&quot; as a hard requirement — because when a platform turns hostile or a region goes down, migration speed <em>is</em> uptime.</p><h2 id="platform-playbook" tabindex="-1">Platform playbook <a class="header-anchor" href="#platform-playbook" aria-label="Permalink to “Platform playbook”">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>What I run there</th></tr></thead><tbody><tr><td>Hugging Face Spaces</td><td>Hermes Stack, AI bridges — generous free compute.</td></tr><tr><td>Cloudflare Workers</td><td>usf-edge panels — KV state, 300+ PoPs, no cold starts.</td></tr><tr><td>Railway / Render / Fly.io / Koyeb</td><td>Panels and APIs — each with its own anti-blocking quirks.</td></tr><tr><td>VPS (Linux)</td><td>Classic deployments, tunnels, monitoring.</td></tr></tbody></table><ul><li><strong>Docker</strong> when the platform supports it; <strong>Procfiles and buildpacks</strong> when it does not.</li><li><strong>CI habits</strong> — GitHub Actions for tests and builds; deploys stay boring on purpose.</li><li><strong>Observability</strong> — structured logs, uptime pings from my own tooling, alerting to Telegram.</li><li><strong>Secrets discipline</strong> — environment variables, encrypted vaults, nothing in git.</li></ul><p>The philosophy matches my <a href="/Usf/en/about/networking/">networking mindset</a>: every deploy is one takedown away from dying, so every deploy has a documented twin on another platform. My panels literally ship five deploy commands for this reason.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};